    ...props }: React.AnchorHTMLAttributes<HTMLAnchorElement>): JSX.Element {
    return <a {...props} className={classNames('mx_ExternalLink', className)} target={target} rel={rel}>
        { children }
        { target === '_blank' && <>
            <span className="mx_ExternalLink_icon" aria-hidden="true" />
